export function userMemorySection(text: string): string | undefined {
  const lines = text.split(/\r?\n/)
  const section = memoriesSection(lines)
  if (!section) return undefined
  const body = lines.slice(section.start, section.end)
  if (!body.some((l) => MEMORY_BULLET.test(l.trim()))) return undefined
  return body.join('\n').trim()
}

/** The person's bullets as entries: one per `## Memories` line, named the way a project note is. `file` is the one file every bullet lives in, so opening any entry opens the same place. */
function userMemoryEntries(text: string, file: string): MemoryEntry[] {
  const lines = text.split(/\r?\n/)
  const section = memoriesSection(lines)
  if (!section) return []
  return lines
    .slice(section.start + 1, section.end)
    .map((l) => MEMORY_BULLET.exec(l.trim()))
    .filter((m): m is RegExpExecArray => m !== null)
    .map((m) => ({ title: m[1]!, file, summary: m[2]! }))
}

/** Drops one bullet from the person's `## Memories` section by its title; a title not found leaves the file untouched. */
export function removeUserMemoryBullet(text: string, title: string): string {
  const lines = text.split(/\r?\n/)
  const section = memoriesSection(lines)
  if (!section) return text
  const { start, end } = section
  const kept = lines
    .slice(start + 1, end)
    .filter((l) => MEMORY_BULLET.test(l.trim()))
    .filter((l) => MEMORY_BULLET.exec(l.trim())![1] !== title)
  const rebuilt = [lines[start]!, '', ...kept, '']
  return [...lines.slice(0, start), ...rebuilt, ...lines.slice(end)].join('\n')
}

/**
 * Every memory kept, for the panel that lists them: the project's notes,
 * rebuilt from the note files on disk so a note added, edited or deleted by
 * hand is already reflected, and the person's own bullets as they stand in
 * their instructions file.
 */
export async function listMemories(cwd: string, home: string = homedir()): Promise<{ project: MemoryEntry[]; user: MemoryEntry[] }> {
  const { entries: project } = await rebuildProjectIndex(projectMemoryDir(cwd, home))
  const path = userMemoryFile(home)
  const text = await readOptional(path)
  const user = text === undefined ? [] : userMemoryEntries(text, basename(path))
  return { project, user }
}

/**
 * Forgets one memory: the note and its index line go for a project memory,
 * rebuilt from what remains on disk; the matching bullet goes for a user one.
 * No later session reads either again, since both are read fresh from these
 * same files at the start of the next one.
 */
export async function forgetMemory(scope: MemoryScope, title: string, cwd: string, home: string = homedir()): Promise<void> {
  if (scope === 'project') {
    const dir = projectMemoryDir(cwd, home)
    const { entries } = await rebuildProjectIndex(dir)
    const entry = entries.find((e) => e.title === title)
    if (!entry) return
    await rm(join(dir, entry.file))
    await rebuildProjectIndex(dir)
    return
  }
  const path = userMemoryFile(home)
  const text = await readOptional(path)
  if (text === undefined) return
  await writeFile(path, removeUserMemoryBullet(text, title), 'utf8')
}

