describe('listMemories', () => {
  it('lists_every_project_note_and_user_bullet_each_with_its_own_scope', async () => {
    const dir = projectMemoryDir(cwd, home)
    await mkdir(dir, { recursive: true })
    await writeFile(join(dir, 'blue.md'), '# Blue means clickable\n\nNon-interactive UI never uses button/badge/focus blue.\n')
    await mkdir(join(home, '.claude'), { recursive: true })
    await writeFile(userMemoryFile(home), '## Memories\n\n- **Likes short replies**: say less, not more.\n')
    const { project, user } = await listMemories(cwd, home)
    expect(project).toEqual([{ title: 'Blue means clickable', file: 'blue.md', summary: 'Non-interactive UI never uses button/badge/focus blue.' }])
    expect(user).toEqual([{ title: 'Likes short replies', file: 'CLAUDE.md', summary: 'say less, not more.' }])
  })

  it('a_note_added_or_deleted_by_hand_since_the_index_was_last_written_is_already_reflected_the_index_is_rebuilt_from_the_notes', async () => {
    const dir = projectMemoryDir(cwd, home)
    await mkdir(dir, { recursive: true })
    await writeFile(join(dir, 'blue.md'), '# Blue means clickable\n\nold wording\n')
    await rebuildProjectIndex(dir)
    // The index now says "old wording"; the note itself is edited by hand, and a second note added, without going through a write the hook sees.
    await writeFile(join(dir, 'blue.md'), '# Blue means clickable\n\nnew wording\n')
    await writeFile(join(dir, 'green.md'), '# Green means safe\n\nsaid so by hand\n')
    expect((await listMemories(cwd, home)).project).toEqual([
      { title: 'Blue means clickable', file: 'blue.md', summary: 'new wording' },
      { title: 'Green means safe', file: 'green.md', summary: 'said so by hand' },
    ])
    // Deleting a note by hand drops it from the listing too, even though the old index line still named it on disk a moment ago.
    await rm(join(dir, 'blue.md'))
    expect((await listMemories(cwd, home)).project).toEqual([{ title: 'Green means safe', file: 'green.md', summary: 'said so by hand' }])
  })

  it('no_memory_file_yet_lists_nothing_for_either_scope', async () => {
    expect(await listMemories(cwd, home)).toEqual({ project: [], user: [] })
  })
})

describe('forgetMemory', () => {
  it('forgetting_a_project_memory_removes_the_note_file_and_its_index_line', async () => {
    const dir = projectMemoryDir(cwd, home)
    await mkdir(dir, { recursive: true })
    await writeFile(join(dir, 'blue.md'), '# Blue means clickable\n\nNon-interactive UI never uses button/badge/focus blue.\n')
    await writeFile(join(dir, 'constraints.md'), '# CodingAgent constraints\n\nSDK pinned to 0.2.112.\n')
    await rebuildProjectIndex(dir)
    await forgetMemory('project', 'Blue means clickable', cwd, home)
    const index = await readFile(join(dir, 'MEMORY.md'), 'utf8')
    expect(index).not.toContain('Blue means clickable')
    expect(index).toContain('CodingAgent constraints')
    await expect(readFile(join(dir, 'blue.md'), 'utf8')).rejects.toThrow()
  })

  it('forgetting_a_user_memory_removes_its_bullet_and_leaves_the_rest_of_the_file', async () => {
    await mkdir(join(home, '.claude'), { recursive: true })
    const path = userMemoryFile(home)
    await writeFile(path, '# Instructions\n\n## Memories\n\n- **Likes short replies**: say less, not more.\n- **Prefers tabs**: not spaces.\n')
    await forgetMemory('user', 'Likes short replies', cwd, home)
    const text = await readFile(path, 'utf8')
    expect(text).not.toContain('Likes short replies')
    expect(text).toContain('Prefers tabs')
    expect(text).toContain('# Instructions')
  })

  it('forgetting_a_title_that_does_not_exist_leaves_everything_as_it_was', async () => {
    const dir = projectMemoryDir(cwd, home)
    await mkdir(dir, { recursive: true })
    await writeFile(join(dir, 'blue.md'), '# Blue means clickable\n\nold wording\n')
    await rebuildProjectIndex(dir)
    await forgetMemory('project', 'No such memory', cwd, home)
    expect(await readFile(join(dir, 'blue.md'), 'utf8')).toContain('old wording')
  })
})

describe('removeUserMemoryBullet', () => {
